def kMirror(k: int, n: int) -> int:
    def fn(x):
        n = len(x) // 2
        for i in range(n, len(x)):
            if int(x[i]) + 1 < k:
                x[i] = x[~i] = str(int(x[i]) + 1)
                for ii in range(n, i):
                    x[ii] = x[~ii] = '0'
                i = n - 1  # Reset i to n - 1 to continue the outer loop
            else:
                break
        return x

    x = ['0']
    ans = 0
    for _ in range(n):
        result = fn(x)
        val = int(''.join(result), k)
        if str(val) == str(val)[::-1]:
            ans += val
    return ans
